//! Keys written by the TypeScript library, loaded through the Rust repositories and client.
//! Fixtures come from `majik-key`'s `tests/vectors/ts-vectors.json` (generated by the TS lib).

use std::sync::{Arc, Mutex};

use majik_key::SerializedIdentity;
use majik_key_client::ipc;
use majik_key_client::{KeyClient, NoHooks, SharedConnection};
use rusqlite::Connection;
use serde_json::Value;

fn fixtures() -> Value {
    serde_json::from_str(include_str!("fixtures/ts_keys.json")).unwrap()
}

fn conn() -> SharedConnection {
    Arc::new(Mutex::new(Connection::open_in_memory().unwrap()))
}

/// Writes a row exactly like the TS `SQLiteKeystoreAdapter`: (id, json, timestamp, public_key).
fn insert_ts_row(conn: &SharedConnection, key_json: &Value) {
    let c = conn.lock().unwrap();
    c.execute_batch(majik_key_client::schema::SCHEMA_MAJIK_KEYS)
        .unwrap();
    c.execute(
        "INSERT OR REPLACE INTO majik_keys (id, json, timestamp, public_key) VALUES (?1, ?2, ?3, ?4)",
        rusqlite::params![
            key_json["id"].as_str().unwrap(),
            key_json.to_string(),
            key_json["timestamp"].as_str().unwrap(),
            key_json["publicKey"].as_str().unwrap(),
        ],
    )
    .unwrap();
}

#[test]
fn a_ts_written_v2_key_loads_registers_unlocks_and_exports() {
    let f = fixtures();
    let pass = f["account"]["passphrase"].as_str().unwrap().to_string();
    let mnemonic = f["account"]["mnemonic"].as_str().unwrap().to_string();
    let key_json = &f["account"]["json"];
    let id = key_json["id"].as_str().unwrap().to_string();

    let conn = conn();
    insert_ts_row(&conn, key_json);

    let mut c = KeyClient::with_sqlite(NoHooks, Arc::clone(&conn)).unwrap();
    let report = c.hydrate().unwrap();
    assert_eq!(report.keys_loaded, 1);
    assert!(report.keys_skipped.is_empty(), "{:?}", report.keys_skipped);
    assert!(
        report.accounts_failed.is_empty(),
        "{:?}",
        report.accounts_failed
    );

    let snap = ipc::snapshot(&c);
    assert_eq!(snap.active_account_id.as_deref(), Some(id.as_str()));
    assert_eq!(
        snap.accounts[0].meta.as_ref().unwrap().label.as_deref(),
        Some("ts-account")
    );
    assert!(!snap.status[0].unlocked && snap.status[0].can_sign);

    assert!(!c.verify_passphrase(&id, "wrong").unwrap());
    c.unlock_account(&id, &pass).unwrap();
    assert!(c.is_account_unlocked(&id));
    // The TS account's own mnemonic produces a backup the Rust side can export.
    assert!(!c
        .export_account_mnemonic_backup(&id, &mnemonic)
        .unwrap()
        .is_empty());

    // Saving it back from Rust keeps it loadable (Rust -> same table -> Rust).
    c.update_account_label(&id, "renamed-in-rust").unwrap();
    let mut c2 = KeyClient::with_sqlite(NoHooks, conn).unwrap();
    c2.hydrate().unwrap();
    assert_eq!(
        c2.get_active_account().unwrap().meta.label.as_deref(),
        Some("renamed-in-rust")
    );
    c2.unlock_account(&id, &pass).unwrap();
}

#[test]
fn a_ts_written_legacy_pbkdf2_key_loads_and_unlocks() {
    let f = fixtures();
    let pass = f["legacyAccount"]["passphrase"]
        .as_str()
        .unwrap()
        .to_string();
    let key_json = &f["legacyAccount"]["json"];
    let id = key_json["id"].as_str().unwrap().to_string();

    let conn = conn();
    insert_ts_row(&conn, key_json);

    let mut c = KeyClient::with_sqlite(NoHooks, conn).unwrap();
    let report = c.hydrate().unwrap();
    assert_eq!(report.keys_loaded, 1);
    assert!(
        report.accounts_failed.is_empty(),
        "{:?}",
        report.accounts_failed
    );
    assert_eq!(
        c.get_active_account().unwrap().meta.label.as_deref(),
        Some("legacy")
    );
    c.unlock_account(&id, &pass).unwrap();
    assert!(c.is_account_unlocked(&id));
}

#[test]
fn migrating_a_pre_registry_serialized_identity_with_real_data() {
    let f = fixtures();
    let k = &f["legacyAccount"]["json"];
    let identity = SerializedIdentity {
        id: k["id"].as_str().unwrap().into(),
        public_key: k["publicKey"].as_str().unwrap().into(),
        fingerprint: k["fingerprint"].as_str().unwrap().into(),
        encrypted_private_key: Some(k["encryptedPrivateKey"].as_str().unwrap().into()),
        salt: Some(k["salt"].as_str().unwrap().into()),
    };
    let mut c = KeyClient::in_memory(NoHooks);
    let summary = ipc::migrate_legacy_identities(&mut c, vec![identity]).unwrap();
    println!("REAL LEGACY MIGRATION: {summary:?}");
    assert_eq!(summary.migrated, 1, "{summary:?}");

    // A pre-registry identity carries only the X25519 key, so the key itself is stored and can be
    // unlocked, but it has no ML-KEM public key and therefore cannot become a MajikContact.
    let pass = f["legacyAccount"]["passphrase"].as_str().unwrap();
    let id = k["id"].as_str().unwrap();
    println!(
        "accounts after migration: {}",
        ipc::snapshot(&c).accounts.len()
    );
    println!("failed registrations: {:?}", summary.accounts_failed);
    assert!(c.key_manager().get(id).is_some());
    assert!(c.verify_passphrase(id, pass).unwrap());
}
